#include <iostream>

class Point {
    public:
        virtual double x() const { return 1.0; }  // Virtual member function
        double y() const { return 2.0; }  // Non-virtual member function
};

int main() {
    double (Point::*coordX)() const = &Point::x;  // Pointer to virtual member function
    double (Point::*coordY)() const = &Point::y;  // Pointer to non-virtual member function
    Point p;
    std::cout << (p.*coordX)() << std::endl;  // Invokes virtual dispatch via vtable
    std::cout << (p.*coordY)() << std::endl;  // Direct call, no vtable
    return 0;
}
